LESSON("l14", "s2", "Simple present: daily habits", "Roz hone wali cheezein", [
    P("**Simple present** un kaamon ke liye jo **roz / aadatan / hamesha** hote hain, ya jo sach hain. Hindi: 'main roz chai peeta **hoon**' → I drink tea every day."),
    P("Rule: verb ka seedha roop. Lekin **he / she / it** ke saath verb mein **-s / -es** lagta hai."),
    TBL(["Subject", "Verb", "Example"], ["I / you / we / they", "go", "They go to school."], ["he / she / it", "goes", "She goes to school."]),
    EX("I drink tea every morning. | मैं हर सुबह चाय पीता हूँ।", "He plays cricket on Sunday. | वह रविवार को क्रिकेट खेलता है।", "The sun rises in the east. | सूरज पूर्व में उगता है।", "She works in a bank. | वह बैंक में काम करती है।"),
    H("-s ya -es?"),
    TBL(["Verb", "He/She/It ke saath"], ["play", "plays"], ["eat", "eats"], ["watch (ch)", "watches"], ["go / do", "goes / does"], ["study (consonant+y)", "studies"], ["have", "has"]),
    H("Negative aur question: do / does"),
    EX("I do not (don't) like tea. | मुझे चाय पसंद नहीं।", "He does not (doesn't) smoke. | वह सिगरेट नहीं पीता।", "Do you play cricket? | क्या तुम क्रिकेट खेलते हो?", "Does she work here? | क्या वह यहाँ काम करती है?"),
    TIP("**does** aate hi main verb se **-s hat jata hai**: 'He plays' lekin 'Does he **play**?' aur 'He doesn't **play**'. Ek sentence mein -s sirf ek jagah."),
    H("Frequency words"),
    P("**always, usually, often, sometimes, never** verb se pehle lagte hain (am/is/are ke baad): 'I **always** wake up early.' 'She is **never** late.'"),
    FIX("He go to office by bus.", "He goes to office by bus.", "He/She/It + verb-s."),
    FIX("Does he plays cricket?", "Does he play cricket?", "does ke saath verb seedha roop."),
], [
    Q("She ___ to school every day.", ["go", "goes", "going", "gone"], 1, "She + goes."),
    Q("They ___ tea in the morning.", ["drinks", "drink", "drinking", "drank"], 1, "They + drink."),
    Q("___ he play football?", ["Do", "Does", "Is", "Are"], 1, "He ke saath Does."),
    Q("He doesn't ___ coffee.", ["likes", "like", "liking", "liked"], 1, "doesn't + seedha verb."),
    Q("study ka he/she form?", ["studys", "studies", "studyes", "study"], 1, "consonant + y → ies."),
])

LESSON("l15", "s2", "Present continuous: happening now", "Abhi ho raha hai", [
    P("**Present continuous** = abhi ho raha kaam. Hindi: 'main kha **raha hoon**'. Banane ka formula: **am / is / are + verb-ing**."),
    EX("I am eating lunch. | मैं दोपहर का खाना खा रहा हूँ।", "She is talking on the phone. | वह फ़ोन पर बात कर रही है।", "They are playing in the park. | वे पार्क में खेल रहे हैं।", "It is raining. | बारिश हो रही है।"),
    TBL(["Verb", "-ing roop"], ["play", "playing"], ["write (e hatao)", "writing"], ["run (last letter double)", "running"], ["sit", "sitting"], ["study", "studying"]),
    H("Negative aur question"),
    EX("I am not sleeping. | मैं सो नहीं रहा।", "He isn't listening. | वह सुन नहीं रहा।", "Are you studying? | क्या तुम पढ़ रहे हो?", "What are you doing? | तुम क्या कर रहे हो?"),
    H("Planned future bhi"),
    P("Pakke plan ke liye bhi use hota hai: 'I **am meeting** him tomorrow.'"),
    EX("We are leaving tomorrow. | हम कल निकल रहे हैं।"),
    TIP("**Kuch verbs ke saath -ing nahi lagta** (state verbs): know, like, love, want, need, understand, have (rakhna). 'I am knowing' galat hai — 'I know' bolo."),
    FIX("I am go to market.", "I am going to the market.", "am/is/are ke baad verb-ing."),
    FIX("I am understanding.", "I understand.", "Understand state verb hai."),
], [
    Q("She ___ a book now.", ["reads", "is reading", "read", "reading"], 1, "Abhi: is reading."),
    Q("They are ___ football.", ["play", "plays", "playing", "played"], 2, "are + playing."),
    Q("write ka -ing roop?", ["writeing", "writing", "writting", "writeng"], 1, "e hatao: writing."),
    Q("Sahi sentence?", ["I am knowing him.", "I know him.", "I am know him.", "I knowing him."], 1, "know state verb hai: I know him."),
    Q("'Tum kya kar rahe ho?'", ["What do you do?", "What are you doing?", "What you doing?", "What is you doing?"], 1, "What are you doing?"),
])

LESSON("l16", "s2", "Simple past: what happened", "Jo ho chuka", [
    P("**Simple past** = bite hue samay (kal, pichhle hafte, 2020 mein) ki khatm ho chuki baat. Hindi: 'main kal market **gaya**'."),
    P("**Regular verbs**: verb ke end mein **-ed** lagao: play→played, work→worked, watch→watched."),
    EX("I played cricket yesterday. | मैं कल क्रिकेट खेला।", "She worked in Delhi last year. | उसने पिछले साल दिल्ली में काम किया।", "We watched a movie. | हमने फ़िल्म देखी।"),
    H("Irregular verbs (yaad karne wale)"),
    TBL(["Aaj", "Beeta hua", "Matlab"], ["go", "went", "gaya"], ["eat", "ate", "khaya"], ["see", "saw", "dekha"], ["take", "took", "liya"], ["come", "came", "aaya"], ["buy", "bought", "kharida"], ["make", "made", "banaya"], ["have", "had", "tha/liya"], ["do", "did", "kiya"], ["give", "gave", "diya"], ["write", "wrote", "likha"], ["speak", "spoke", "bola"]),
    EX("I went to the market. | मैं बाज़ार गया।", "He ate rice. | उसने चावल खाए।", "They came late. | वे देर से आए।", "She bought a phone. | उसने एक फ़ोन ख़रीदा।"),
    H("Negative aur question: did"),
    EX("I did not (didn't) go. | मैं नहीं गया।", "Did you see him? | क्या तुमने उसे देखा?", "Where did you go? | तुम कहाँ गए थे?"),
    TIP("**did** aate hi main verb **seedha roop** mein: 'I **went**' lekin 'I didn't **go**' aur 'Did you **go**?' Ye sabse common galti hai."),
    P("Past mein **am/is/are** ban jate hain **was/were**: I/he/she/it **was**, you/we/they **were**."),
    EX("I was at home. | मैं घर पर था।", "They were happy. | वे ख़ुश थे।"),
    FIX("I didn't went there.", "I didn't go there.", "Did/didn't ke baad verb seedha roop."),
    FIX("Yesterday I have seen him.", "Yesterday I saw him.", "Bite samay (yesterday) ke saath simple past."),
], [
    Q("I ___ to school yesterday.", ["go", "went", "gone", "going"], 1, "go ka past: went."),
    Q("She ___ a movie last night.", ["watch", "watched", "watches", "watching"], 1, "Regular verb + ed."),
    Q("Did you ___ him?", ["saw", "see", "seen", "sees"], 1, "Did + seedha verb."),
    Q("They ___ at home yesterday.", ["was", "were", "are", "is"], 1, "They + were."),
    Q("eat ka past?", ["eated", "ate", "eaten", "eats"], 1, "eat → ate."),
])

LESSON("l17", "s2", "Future: will and going to", "Aage kya hoga", [
    P("Future ke do aasan tareeke. **will + verb** = abhi liya hua faisla, vaada, ya anuman. **am/is/are going to + verb** = pehle se soch rakha plan."),
    EX("I will call you tomorrow. | मैं तुम्हें कल फ़ोन करूँगा।", "It will rain tonight. | आज रात बारिश होगी।", "I will help you. | मैं तुम्हारी मदद करूँगा।"),
    EX("I am going to study tonight. | मैं आज रात पढ़ाई करने वाला हूँ।", "She is going to buy a car. | वह कार ख़रीदने वाली है।", "We are going to visit Agra. | हम आगरा जाने वाले हैं।"),
    TBL(["", "will", "going to"], ["Kab", "turant faisla / vaada", "pehle se plan"], ["Example", "I will open the door.", "I am going to learn Java."], ["Negative", "will not (won't)", "am/is/are not going to"], ["Question", "Will you come?", "Are you going to come?"]),
    H("Time words"),
    P("**tomorrow, next week, next month, soon, tonight, in two days** — ye future ke saath aate hain."),
    EX("See you tomorrow. | कल मिलते हैं।", "I will be there in ten minutes. | मैं दस मिनट में वहाँ पहुँचूँगा।", "I won't forget. | मैं भूलूँगा नहीं।"),
    FIX("I will going to market.", "I am going to the market.", "will aur going to ek saath nahi aate."),
    FIX("She will comes tomorrow.", "She will come tomorrow.", "will ke baad seedha verb."),
], [
    Q("I ___ call you later. (vaada)", ["will", "am", "did", "have"], 0, "Vaada: will."),
    Q("She is going ___ buy a phone.", ["to", "for", "at", "on"], 0, "going to + verb."),
    Q("Sahi sentence?", ["She will comes.", "She will come.", "She wills come.", "She will to come."], 1, "will + seedha verb."),
    Q("'Main nahi bhoolunga' =", ["I will not forget.", "I not will forget.", "I will not forgot.", "I don't will forget."], 0, "will not forget."),
    Q("'Pehle se plan' ke liye kya behtar?", ["going to", "did", "was", "have"], 0, "Plan = going to."),
])

LESSON("l18", "s2", "Present perfect: have / has + done", "Abhi tak kiya hai", [
    P("**Present perfect** = beeta hua kaam jiska **asar ya sambandh aaj se hai**, ya jiska **samay nahi bataya**. Formula: **have/has + past participle (V3)**."),
    EX("I have finished my work. | मैंने अपना काम ख़त्म कर लिया है।", "She has lost her key. | उसने अपनी चाबी खो दी है।", "I have seen this movie. | मैंने यह फ़िल्म देखी है।", "Have you eaten? | क्या तुमने खाना खा लिया है?"),
    TBL(["Verb", "V2 (past)", "V3 (participle)"], ["go", "went", "gone"], ["eat", "ate", "eaten"], ["see", "saw", "seen"], ["take", "took", "taken"], ["do", "did", "done"], ["write", "wrote", "written"], ["finish", "finished", "finished"]),
    H("for aur since"),
    P("**since** = kab se (shuru hone ka point): since 2020, since morning. **for** = kitne samay se: for two years, for an hour."),
    EX("I have lived here for five years. | मैं यहाँ पाँच साल से रह रहा हूँ।", "She has worked here since 2022. | वह 2022 से यहाँ काम कर रही है।", "I have known him for ten years. | मैं उसे दस साल से जानता हूँ।"),
    H("Kab simple past, kab present perfect?"),
    P("**Kal / pichhle hafte / 2020 mein** jaise bite samay ke saath → **simple past** ('I saw him yesterday'). Samay nahi bataya ya 'abhi tak' → **present perfect** ('I have seen him')."),
    EX("I have already eaten. | मैं पहले ही खा चुका हूँ।", "I have never been to Goa. | मैं कभी गोवा नहीं गया।", "Have you ever flown? | क्या तुम कभी हवाई जहाज़ में बैठे हो?"),
    FIX("I have seen him yesterday.", "I saw him yesterday.", "'yesterday' bita hua pakka samay hai — simple past."),
    FIX("I am living here since 2020.", "I have lived here since 2020.", "since ke saath present perfect."),
], [
    Q("I ___ finished my work.", ["has", "have", "am", "did"], 1, "I + have + V3."),
    Q("She ___ gone home.", ["have", "has", "is", "did"], 1, "She + has."),
    Q("I have lived here ___ 2020.", ["for", "since", "from", "at"], 1, "Shuru ka point: since."),
    Q("I have lived here ___ five years.", ["for", "since", "from", "at"], 0, "Avadhi: for."),
    Q("Sahi sentence?", ["I have seen him yesterday.", "I saw him yesterday.", "I have saw him yesterday.", "I seen him yesterday."], 1, "yesterday → simple past."),
])

LESSON("l19", "s2", "Asking and answering in past, present and future", "Teeno kaal mein sawaal-jawab ka practice", [
    P("Ab tak ke teen formula ek jagah rakhte hain. Sawaal banane ka tareeka **helping verb** se pehchano: **do/does** (present), **did** (past), **will** (future), **am/is/are** (continuous), **have/has** (perfect)."),
    TBL(["Kaal", "Sawaal", "Jawab"],
        ["Present", "Do you drink tea?", "Yes, I do. / No, I don't."], ["Present", "Does she work here?", "Yes, she does."], ["Past", "Did you go there?", "Yes, I did. / No, I didn't."], ["Future", "Will you come?", "Yes, I will. / No, I won't."], ["Now", "Are you studying?", "Yes, I am."], ["Perfect", "Have you eaten?", "Yes, I have. / No, I haven't."]),
    EX("Do you like coffee? | क्या तुम्हें कॉफ़ी पसंद है?", "Yes, I do. | हाँ, पसंद है।", "Did you sleep well? | क्या तुम अच्छे से सोए?", "No, I didn't. | नहीं, नहीं सोया।", "Will you join us? | क्या तुम हमारे साथ आओगे?", "Yes, I will. | हाँ, आऊँगा।"),
    TIP("**Short answer** mein wahi helping verb dohrao jo sawaal mein tha: Did you...? → Yes, I **did**. Ye natural bolchaal ka raaz hai."),
    H("Wh- sawaal teeno kaal mein"),
    EX("What do you do? | आप क्या करते हैं?", "What did you eat? | तुमने क्या खाया?", "Where will you go? | तुम कहाँ जाओगे?", "What are you doing? | तुम क्या कर रहे हो?", "Where have you been? | तुम कहाँ थे?"),
], [
    Q("'Do you like tea?' ka short jawab?", ["Yes, I like.", "Yes, I do.", "Yes, I am.", "Yes, I did."], 1, "Do → Yes, I do."),
    Q("'Did she come?' ka short jawab?", ["Yes, she did.", "Yes, she does.", "Yes, she came.", "Yes, she is."], 0, "Did → she did."),
    Q("___ you coming tomorrow?", ["Do", "Are", "Did", "Does"], 1, "Continuous: Are you coming?"),
    Q("What ___ you eat yesterday?", ["do", "did", "will", "are"], 1, "Past: did."),
    Q("'Will you help?' ka jawab?", ["Yes, I will.", "Yes, I do.", "Yes, I did.", "Yes, I am."], 0, "will → I will."),
])
